function roundedRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r);
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h);
  ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

function drawSparkle(ctx, x, y, size) {
  ctx.beginPath();
  ctx.moveTo(x, y - size);
  ctx.lineTo(x + size * 0.25, y - size * 0.25);
  ctx.lineTo(x + size, y);
  ctx.lineTo(x + size * 0.25, y + size * 0.25);
  ctx.lineTo(x, y + size);
  ctx.lineTo(x - size * 0.25, y + size * 0.25);
  ctx.lineTo(x - size, y);
  ctx.lineTo(x - size * 0.25, y - size * 0.25);
  ctx.closePath();
  ctx.fillStyle = '#fff2a6';
  ctx.fill();
}

export function createFilter(host) {
  host.onFrame(({ ctx, width, height, faces }) => {
    const face = faces?.[0];
    const p = face?.landmarks;
    if (!p?.leftEye || !p.rightEye) return;

    const left = { x: p.leftEye.x * width, y: p.leftEye.y * height };
    const right = { x: p.rightEye.x * width, y: p.rightEye.y * height };
    const dx = right.x - left.x;
    const dy = right.y - left.y;
    const eyeSpan = Math.hypot(dx, dy);
    if (eyeSpan < 1) return;

    const raise = face.expressions?.browRaise ?? 0;
    ctx.save();
    ctx.translate((left.x + right.x) / 2, (left.y + right.y) / 2);
    ctx.rotate(Math.atan2(dy, dx));
    ctx.scale(eyeSpan, eyeSpan);

    ctx.lineWidth = 0.055;
    ctx.strokeStyle = '#c9873c';
    ctx.fillStyle = 'rgba(120, 213, 194, 0.28)';

    roundedRect(ctx, -0.94, -0.29, 0.83, 0.58, 0.13);
    ctx.fill();
    ctx.stroke();
    roundedRect(ctx, 0.11, -0.29, 0.83, 0.58, 0.13);
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(-0.11, -0.03);
    ctx.quadraticCurveTo(0, -0.14, 0.11, -0.03);
    ctx.stroke();

    if (raise > 0.65) {
      drawSparkle(ctx, -0.53, -0.46, 0.12);
      drawSparkle(ctx, 0.53, -0.46, 0.12);
    }

    ctx.restore();
  });
}
